message.content:
{
  "base_revision": "sha256:b23b9dec74fe60f4626fbf664fffc229f4fcad58100b0677bfcd2d82aa077342",
  "decision": "revise",
  "issues": [
    "rail_presentation: FAIL - The VPLUS and VMINUS rails are not correctly presented. Terminals for these nets (e.g., J1.3, J1.4, U1.8, U1.4) are in separate wire groups that are neither joined by a continuous wire nor marked by a matching power symbol.",
    "diagnostics: The diagnostics confirm that wire groups for VPLUS and VMINUS nets lack the required connection to the rest of their rail or a marking power symbol."
  ],
  "actions": [
    {
      "operation": "use_power_symbols",
      "net": "VPLUS"
    }
  ],
  "rationale": "The independent assessment reports a FAIL for 'rail_presentation' on the VPLUS and VMINUS nets. The diagnostics explicitly state that wire groups for these nets are neither joined nor marked by power symbols. Per the review brief, when rail_presentation fails, we must request 'use_power_symbols' to re-place only that rail's symbols. The previous feedback suggests using this operation first to replace existing wiring with power symbols before attempting further edits like connect_rail."
}
